"""Page content and route registry."""
from .components import *
def home(route):
 cards=''.join(project(p,route) for p in P if p.get('featured'))
 if not cards:cards=''.join(project(p,route) for p in P[:3])
 return f'''<section class="hero"><div class="wrap hero-inner"><div><div class="eyebrow">Разработка · Сервисы · Технологии</div><h1>Создаём цифровые<br>продукты <span class="accent">с характером.</span></h1><p>Kodumi — независимый бренд разработки. Создаём веб-платформы, приложения и программные решения, объединяя технологии и продуманный дизайн.</p><div class="actions">{link('/projects/','Наши проекты',route,'btn primary','arrow')}{link('/about/','О компании',route,'btn','arrow')}</div></div><img class="hero-art" src="assets/hero-laptop.webp" alt="" width="510" height="234"></div></section>
 <div class="wrap"><section class="section home-grid"><div>{sectionhead('Чем мы занимаемся','От идеи до работающего продукта.',route,'/services/','Все направления')}<div class="services-grid">{service_cards(route)}</div></div><aside class="panel"><h2>О Kodumi</h2><p>Единая экосистема самостоятельных проектов. Мы развиваем продукты, уделяя внимание удобству, архитектуре и деталям.</p>{link('/about/','Читать о Kodumi',route,'textlink','arrow')}</aside></section>
 <section class="section home-grid"><div>{sectionhead('Наши проекты','Продукты и разработки экосистемы Kodumi.',route,'/projects/','Все проекты')}<div class="project-grid home-projects">{cards}<div class="placeholder">{ico('layers')}<h3>Новые проекты</h3><p>Каталог будет пополняться по мере развития наших продуктов.</p>{link('/projects/','Открыть каталог',route,'textlink','arrow')}</div></div></div><aside class="panel"><h2>Наш подход</h2><div class="checks">{''.join(f'<div class="check">{ico("check")}<span>{s}</span></div>' for s in ['Продуманная архитектура','Удобные и адаптивные интерфейсы','Развитие продуктов после запуска','Отдельная идентичность каждого проекта'])}</div></aside></section>
 <section class="section">{sectionhead('Технологии','Выберите технологию, чтобы увидеть связанные проекты.',route,'/technologies/','Все технологии')}<div class="tech-strip">{''.join(techchip(t,route) for t in T.values())}</div></section><section class="section">{portfolio_banner(route)}</section></div>'''
def intro(title,desc,route,parents=[]):
 crumbs=link('/','Главная',route)+''.join(' <span>/</span> '+link(t,n,route) for t,n in parents)+' <span>/</span> <span aria-current="page">'+E(title)+'</span>'
 return f'<div class="wrap inner-page"><nav class="crumbs" aria-label="Хлебные крошки">{crumbs}</nav><div class="page-intro"><h1>{E(title)}</h1><p>{E(desc)}</p></div>'
def filters(route,selected):
 return '<nav class="filters" aria-label="Категории проектов">'+''.join(link(t,n,route,'filter',attrs='aria-current="page"' if k==selected else '') for k,t,n in [('all','/projects/','Все проекты')]+[(k,'/projects/category/'+k+'/',n) for k,n in cats.items()])+'</nav>'
def catalog(route,cat=None):
 name=cats[cat] if cat else 'Все проекты'; ps=[p for p in P if not cat or p['category']==cat]
 return intro(name,'Каталог продуктов Kodumi. Выберите категорию или откройте проект, чтобы узнать больше.',route,[('/projects/','Проекты')] if cat else [])+filters(route,cat or 'all')+'<div class="tech-strip" style="margin-bottom:20px">'+''.join(techchip(t,route) for t in T.values())+'</div>'+('<div class="project-grid catalog">'+''.join(project(p,route) for p in ps)+'</div>' if ps else empty(route,'Проекты этой категории появятся здесь после публикации.'))+'</div>'
def technology(route,t):
 ps=[p for p in P if t['slug'] in p['technologies']]
 return intro(t['name'],t['description'],route,[('/technologies/','Технологии')])+f'<div class="tech-intro-card" style="--tech:{E(t["color"])}">{tech_symbol(t)}<div><span class="stack-label">ТЕХНОЛОГИЯ</span><h2>{E(t["name"])}</h2><p>{E(t["description"])}</p></div><div class="tech-count"><strong>{len(ps)}</strong><span>проектов в каталоге</span></div></div>'+sectionhead('Проекты на '+E(t['name']),'',route)+('<div class="project-grid catalog">'+''.join(project(p,route) for p in ps)+'</div>' if ps else empty(route,'Публичные проекты с этой технологией будут добавлены позже.'))+'</div>'
def technologies(route):
 return intro('Технологии','Направления разработки и инструменты. Откройте технологию, чтобы увидеть соответствующие проекты.',route)+'<div class="tech-grid">'+''.join(f'<a class="tech-card" style="--tech:{E(t["color"])}" href="{rel("/technologies/"+t["slug"]+"/",route)}">{tech_symbol(t)}<h3>{E(t["name"])}</h3><p>{E(t["description"])}</p><span class="textlink">Проекты · {sum(t["slug"] in p["technologies"] for p in P)} {ico("arrow")}</span></a>' for t in T.values())+'</div></div>'
def detail(route,p):
 launch=ext(p['url'],'Открыть проект','btn primary') if p.get('url') else '<p class="notice">Публичная ссылка на проект будет добавлена отдельно.</p>'
 return intro(p['name'],p['summary'],route,[('/projects/','Проекты')])+f'<div class="detail-grid"><div>{project_cover(p,route)}<div class="prose subsection"><h2>О проекте</h2><p>{E(p["description"])}</p><h2>Возможности</h2><ul>'+''.join(f'<li>{E(f)}</li>' for f in p.get('features',[]))+f'</ul></div>{gallery(p,route)}</div><aside class="panel stack-panel"><span class="status">{E(p["status"])}</span><h2 style="margin-top:12px">Технологии проекта</h2><p>Что использовалось при разработке.</p>{project_stack(p,route)}<div class="subsection">{launch}</div></aside></div></div>'
PAGES={}
def add(route,title,desc,content,og='assets/social.png',index=True):PAGES[route]=(title,desc,content,og,index)
add('/','Kodumi — цифровые продукты и разработка','Kodumi: веб-платформы, программные решения, проекты и технологии.',home('/'))
add('/projects/','Проекты','Каталог проектов и продуктов Kodumi.',catalog('/projects/'))
for k,n in cats.items():r='/projects/category/'+k+'/';add(r,n,'Проекты Kodumi: '+n+'.',catalog(r,k))
for p in P:r='/projects/'+p['slug']+'/';add(r,p['name'],p['summary'],detail(r,p),og=project_image(p) or 'assets/social.png')
add('/technologies/','Технологии','Технологии и связанные проекты Kodumi.',technologies('/technologies/'))
for t in T.values():r='/technologies/'+t['slug']+'/';add(r,t['name']+' — проекты',t['description'],technology(r,t))
r='/services/';add(r,'Направления разработки','Игровые платформы, веб-разработка, программные решения и индивидуальные проекты.',intro('Направления разработки','Основные направления, в которых развиваются продукты Kodumi.',r)+'<div class="service-detail">'+service_cards(r,True)+'</div></div>')
r='/about/';add(r,'О Kodumi','О бренде Kodumi и его подходе к разработке.',intro('О Kodumi','Единый бренд для самостоятельных цифровых продуктов.',r)+f'<div class="detail-grid"><div class="prose"><h2>Что такое Kodumi?</h2><p>Kodumi объединяет цифровые проекты под общей идентичностью. Каждый продукт сохраняет свой собственный интерфейс, назначение и особенности.</p><h2>Как мы работаем</h2><p>В центре внимания — понятный интерфейс, продуманная архитектура и постепенное развитие продукта.</p><h2>Kodumi и Kodumi Games</h2><p>Kodumi — основной бренд. Kodumi Games — отдельная игровая платформа в его экосистеме.</p>{link("/projects/","Наши проекты",r,"btn primary","arrow")}</div><aside class="panel"><h2>Экосистема</h2><p>Проекты, технологии и личное портфолио разработчика представлены отдельно, чтобы было проще найти нужное.</p>{link("/portfolio/","Портфолио",r,"textlink","arrow")}</aside></div></div>')
r='/contacts/'; contacts=[]
if D['email']:contacts.append(f'<a class="btn" href="mailto:{E(D["email"])}">{ico("mail")}{E(D["email"])}</a>')
for key,label in [('telegramUrl','Telegram'),('githubUrl','GitHub')]:
 if D[key]:contacts.append(ext(D[key],label,'btn'))
add(r,'Контакты','Контактная информация Kodumi.',intro('Контакты','Связь по вопросам проектов и сотрудничества.',r)+'<div class="panel"><h2>Связаться с Kodumi</h2>'+('<div class="actions">'+''.join(contacts)+'</div>' if contacts else '<p>Контактные данные будут опубликованы после настройки сайта.</p>')+'</div></div>')
r='/portfolio/';add(r,'Портфолио разработчика','Личное портфолио разработчика Kodumi.',intro('Личное портфолио разработчика','Отдельный ресурс о профессиональных навыках, личных проектах и опыте.',r)+f'<div class="panel"><h2>Портфолио</h2><p>Личное портфолио не является каталогом продуктов Kodumi.</p><div class="subsection">'+(ext(D['portfolioUrl'],'Открыть портфолио','btn primary') if D['portfolioUrl'] else '<p class="notice">Ссылка на отдельный сайт портфолио будет добавлена после его публикации.</p>')+'</div></div></div>')
for r,title,body in [('/privacy/','Политика конфиденциальности','<h2>Информация о данных</h2><p>На текущем сайте не реализованы формы регистрации, аналитика или рекламные трекеры. Хостинг может обрабатывать технические данные посещений. Другие продукты Kodumi могут иметь собственные правила.</p><p>Перед публикацией необходимо уточнить сведения об операторе, хостинге, обработке данных и контактах.</p>'),('/terms/','Условия использования','<h2>Материалы сайта</h2><p>Сайт знакомит посетителей с проектами Kodumi. Использование отдельных продуктов регулируется условиями этих продуктов. Права на сторонние материалы и названия принадлежат их владельцам.</p><p>Перед публикацией необходимо утвердить окончательные условия и сведения о правообладателе.</p>')]:add(r,title,title+' Kodumi.',intro(title,'Информация о правилах сайта.',r)+'<div class="prose">'+body+'</div></div>',index=False)
add('/404.html','Страница не найдена','Запрошенная страница не найдена.',intro('Страница не найдена','Возможно, адрес изменился или страница ещё не опубликована.','/')+link('/','На главную','/','btn primary','arrow')+'</div>',index=False)
